import { NextResponse } from 'next/server';
import { spawn } from 'child_process';
import path from 'path';

export async function POST(req: Request) {
  try {
    const { text } = await req.json();

    const scriptPath = path.join(process.cwd(), 'scripts', 'my_script.py');

    return new Promise((resolve) => {
      const py = spawn('python3', [scriptPath, text],{
        env: {
          ...process.env,
          PYTHONIOENCODING: 'utf-8', // ✅ ép stdout/stderr xuất ra Unicode
        },
      });

      let output = '';
      let errorOutput = '';

      py.stdout.on('data', (data) => {
        output += data.toString();
      });

      py.stderr.on('data', (data) => {
        errorOutput += data.toString();
      });

      py.on('close', (code) => {
        if (code === 0) {
          resolve(NextResponse.json({ result: output.trim() }));
        } else {
          resolve(
            NextResponse.json(
              { error: errorOutput || 'Lỗi không xác định khi chạy Python.' },
              { status: 500 }
            )
          );
        }
      });
    });
  } catch (e: any) {
    return NextResponse.json(
      { error: 'Lỗi trong quá trình xử lý request hoặc đọc JSON body.' },
      { status: 400 }
    );
  }
}
